import { expect, test } from "vite-plus/test";
import * as NodeModule from "node:module";
import { installStorage } from "./xhr-shim.ts";

// `message_keys` is generated by the Pebble build, so tests point require() at a stand-in.
const messageKeys = new URL("./message-keys.js", import.meta.url).href;
NodeModule.registerHooks({
  resolve: (specifier, context, nextResolve) =>
    specifier === "message_keys"
      ? { url: messageKeys, shortCircuit: true }
      : nextResolve(specifier, context),
});

const encoder = (value: unknown) => encodeURIComponent(JSON.stringify(value));

function item(itemId: string, status: string, text: string) {
  return { itemId, type: "assistant_message", status, text };
}

async function setup() {
  const handlers: Record<string, (event: any) => void> = {};
  const outbox: { message: any; success: () => void; failure: () => void }[] = [];
  const attempts: any[] = [];
  const pending: FakeXhr[] = [];
  let poll: (() => void) | undefined;
  let pumping = false;

  const script = {
    items: [] as any[],
    itemCount: 1,
    holdThreads: false,
    holdSpeech: true,
    readError: false,
    sendError: false,
    threadStatus: "",
    pcm: new Uint8Array([1, 2]).buffer as ArrayBuffer,
  };

  class FakeXhr {
    status = 0;
    responseText = "";
    response: unknown = null;
    responseType = "";
    timeout = 0;
    onload: (() => void) | null = null;
    onerror: (() => void) | null = null;
    ontimeout: (() => void) | null = null;
    url = "";
    body = "";
    private received = new Headers();

    open(_method: string, url: string) {
      this.url = url;
    }
    setRequestHeader() {}
    getResponseHeader(name: string) {
      return this.received.get(name);
    }
    send(body?: string | null) {
      this.body = body ?? "";
      pending.push(this);
      pump();
    }
    json(payload: unknown, headers: Record<string, string> = {}) {
      this.status = 200;
      for (const [key, value] of Object.entries(headers)) this.received.set(key, value);
      this.responseText = JSON.stringify(payload);
      this.onload?.();
    }
    fail(status: number) {
      this.status = status;
      this.responseText = "failed";
      this.onload?.();
    }
    buffer(data: ArrayBuffer) {
      this.status = 200;
      this.response = data;
      this.onload?.();
    }
  }

  function respond(xhr: FakeXhr): boolean {
    if (xhr.url.includes("api.elevenlabs.io")) {
      if (script.holdSpeech) return false;
      xhr.buffer(script.pcm);
      return true;
    }
    const request = JSON.parse(xhr.body);
    if (request.method === "notifications/initialized") {
      xhr.status = 202;
      xhr.onload?.();
      return true;
    }
    if (request.method === "initialize") {
      xhr.json(
        { jsonrpc: "2.0", id: request.id, result: { protocolVersion: "2025-03-26" } },
        { "mcp-session-id": "session" },
      );
      return true;
    }
    const result = (value: unknown) => {
      xhr.json({ jsonrpc: "2.0", id: request.id, result: value });
      return true;
    };
    switch (request.params.name) {
      case "t3_thread_list":
        if (script.holdThreads) return false;
        return result({ threads: [], nextCursor: null });
      case "t3_environment_read":
        return result({ label: "Mac" });
      case "t3_project_list":
        return result({ projects: [], nextCursor: null });
      case "t3_thread_read":
        if (script.readError) {
          xhr.fail(500);
          return true;
        }
        return result(
          request.params.arguments.limit === 1
            ? { thread: { itemCount: script.itemCount }, items: [] }
            : script.threadStatus
              ? { items: script.items, thread: { status: script.threadStatus } }
              : { items: script.items },
        );
      case "t3_thread_send":
        if (script.sendError) {
          xhr.fail(500);
          return true;
        }
        return result({ runId: "run" });
      default:
        return result({});
    }
  }

  function pump() {
    if (pumping) return;
    pumping = true;
    try {
      for (let index = 0; index < pending.length;) {
        const xhr = pending[index]!;
        if (!respond(xhr)) {
          index++;
          continue;
        }
        pending.splice(index, 1);
      }
    } finally {
      pumping = false;
    }
  }

  function take(match: (xhr: FakeXhr) => boolean) {
    const index = pending.findIndex(match);
    if (index < 0) throw new Error("no held request matched");
    return pending.splice(index, 1)[0]!;
  }

  const pebble = {
    addEventListener(name: string, callback: (event: any) => void) {
      handlers[name] = callback;
    },
    sendAppMessage(message: any, success: () => void, failure: () => void) {
      attempts.push(message);
      outbox.push({ message, success, failure });
    },
    openURL() {},
    showSimpleNotificationOnPebble() {},
  };

  const storage = installStorage({
    mcpUrl: "https://test",
    mcpToken: "watch-token",
    elevenKey: "eleven-key",
  });
  const originalInterval = globalThis.setInterval;
  const originalClear = globalThis.clearInterval;
  (globalThis as any).Pebble = pebble;
  (globalThis as any).XMLHttpRequest = FakeXhr;
  globalThis.setInterval = ((callback: () => void) => {
    poll = callback;
    return 1;
  }) as typeof setInterval;
  globalThis.clearInterval = (() => {
    poll = undefined;
  }) as typeof clearInterval;

  return {
    script,
    attempts,
    outbox,
    storage,
    handlers,
    ready() {
      handlers.ready!({});
    },
    open(thread: string) {
      handlers.appmessage!({ payload: { action: "read", thread } });
    },
    close() {
      handlers.appmessage!({ payload: { action: "close" } });
    },
    appmessage(payload: Record<string, unknown>) {
      handlers.appmessage!({ payload });
    },
    poll() {
      if (!poll) throw new Error("no read poll scheduled");
      poll();
    },
    drain() {
      while (outbox.length) outbox.shift()!.success();
    },
    reject() {
      const head = outbox.shift();
      if (!head) throw new Error("nothing to reject");
      head.failure();
    },
    releaseThreads() {
      take((xhr) => xhr.body.includes("t3_thread_list")).json({
        jsonrpc: "2.0",
        id: 1,
        result: { threads: [], nextCursor: null },
      });
      pump();
    },
    speech(text: string) {
      return pending.find(
        (xhr) => xhr.url.includes("api.elevenlabs.io") && xhr.body.includes(text),
      );
    },
    releaseSpeech(text: string, pcm: ArrayBuffer) {
      take((xhr) => xhr.url.includes("api.elevenlabs.io") && xhr.body.includes(text)).buffer(pcm);
      pump();
    },
    config(response: unknown) {
      handlers.webviewclosed!({ response: encoder(response) });
    },
    restore() {
      globalThis.setInterval = originalInterval;
      globalThis.clearInterval = originalClear;
      storage.restore();
    },
  };
}

const pcm = (bytes: number) => new Uint8Array(bytes).fill(9).buffer;

test("ignores speech that resolves after a newer reply or after the thread closes", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=speech");
    harness.ready();
    harness.drain();
    harness.open("1");
    harness.drain();
    expect(harness.speech("alpha reply")).toBeUndefined();
    harness.script.items = [item("a1", "completed", "alpha reply")];
    harness.poll();
    expect(harness.speech("alpha reply")).toBeDefined();

    harness.script.items = [item("a2", "completed", "beta reply")];
    harness.poll();
    harness.releaseSpeech("beta reply", pcm(8));
    harness.drain();
    expect(harness.attempts.filter((message) => message.action === "audio_start")).toHaveLength(1);

    harness.releaseSpeech("alpha reply", pcm(40));
    harness.drain();
    expect(harness.attempts.filter((message) => message.action === "audio_start")).toHaveLength(1);

    harness.script.items = [item("a3", "completed", "gamma reply")];
    harness.poll();
    harness.close();
    harness.releaseSpeech("gamma reply", pcm(8));
    harness.drain();
    expect(harness.attempts.filter((message) => message.action === "audio_start")).toHaveLength(1);
  } finally {
    harness.restore();
  }
});

test("discards a thread list that resolves after a thread was opened", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=list");
    harness.script.holdThreads = true;
    harness.ready();
    harness.drain();
    const listed = harness.attempts.length;

    harness.open("1");
    harness.drain();
    const beforeRelease = harness.attempts.length;
    harness.releaseThreads();
    harness.drain();

    expect(harness.attempts.length).toBe(beforeRelease);
    expect(harness.attempts.slice(listed).some((message) => message.action === "clear")).toBe(
      false,
    );
    expect(harness.attempts.slice(listed).some((message) => message.action === "thread")).toBe(
      false,
    );
  } finally {
    harness.restore();
  }
});

test("retries a failed packet twice, then drops only that packet", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=retry");
    harness.ready();
    expect(harness.outbox[0]!.message.action).toBe("clear");

    harness.reject();
    harness.reject();
    expect(harness.outbox[0]!.message.action).toBe("clear");

    const clearAttempts = () => harness.attempts.filter((message) => message.action === "clear");
    expect(clearAttempts()).toHaveLength(3);
    expect(new Set(clearAttempts().map((message) => JSON.stringify(message))).size).toBe(1);

    harness.reject();
    expect(harness.outbox[0]!.message.action).not.toBe("clear");
    expect(clearAttempts()).toHaveLength(3);
  } finally {
    harness.restore();
  }
});

test("abandons an audio transfer when its packets exhaust retries", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=audio");
    harness.ready();
    harness.drain();
    harness.open("1");
    harness.drain();
    harness.script.pcm = pcm(2400 * 2);
    harness.script.items = [item("a1", "completed", "speak this")];
    harness.poll();
    harness.releaseSpeech("speak this", harness.script.pcm);
    harness.drain();
    expect(harness.attempts.at(-1).action).toBe("audio");

    harness.appmessage({ action: "audio_ack" });
    harness.appmessage({ action: "audio_ack" });
    expect(harness.outbox).toHaveLength(1);

    const audioAttempts = () =>
      harness.attempts.filter((message) => message.action === "audio").length;
    expect(audioAttempts()).toBe(2);
    harness.reject();
    harness.reject();
    harness.reject();
    expect(audioAttempts()).toBe(4);
    expect(harness.outbox).toHaveLength(0);
    expect(harness.attempts.some((message) => message.action === "audio_play")).toBe(false);

    harness.appmessage({ action: "audio_ack" });
    expect(harness.outbox).toHaveLength(0);
    expect(audioAttempts()).toBe(4);
  } finally {
    harness.restore();
  }
});

test("caps chat item and summary fields at 150 bytes and messages at 900 bytes", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=bytes");
    harness.ready();
    harness.drain();
    harness.script.items = [
      {
        itemId: "😀".repeat(100),
        type: "assistant_message",
        status: "completed",
        text: "**" + "字".repeat(400) + "**",
      },
      {
        itemId: "c" + "字".repeat(200),
        type: "command_execution",
        status: "completed",
        title: "字".repeat(200),
        text: "run",
      },
    ];
    harness.open("1");
    harness.drain();
    const chats = harness.attempts.filter((message) => message.action === "chat_item");
    expect(chats.length).toBeGreaterThan(1);
    for (const chat of chats) {
      expect(Buffer.byteLength(chat.item, "utf8")).toBeLessThanOrEqual(150);
      expect(Buffer.byteLength(chat.summary, "utf8")).toBeLessThanOrEqual(150);
      expect(Buffer.byteLength(chat.message, "utf8")).toBeLessThanOrEqual(900);
      expect(chat.message).not.toContain("\uFFFD");
      expect(Buffer.from(chat.message, "utf8").toString("utf8")).toBe(chat.message);
    }
    const assistant = chats.find((message) => message.title === "assistant_message");
    expect(Buffer.byteLength(assistant.message, "utf8")).toBeGreaterThan(800);
    expect(assistant.message.endsWith("\x01")).toBe(true);
    expect(Buffer.byteLength(chats.at(-1).summary, "utf8")).toBeGreaterThan(0);
  } finally {
    harness.restore();
  }
});

test("drops empty assistant placeholders and empty work groups so Thinking shows", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=blank");
    harness.ready();
    harness.drain();
    harness.script.threadStatus = "running";
    harness.script.items = [
      { itemId: "w1", type: "reasoning", status: "completed", title: "", text: "" },
      { itemId: "u1", type: "user_message", status: "completed", text: "hello" },
      { itemId: "a1", type: "assistant_message", status: "running", text: "" },
    ];
    harness.open("1");
    harness.drain();

    const chats = harness.attempts.filter((message) => message.action === "chat_item");
    expect(chats.map((message) => message.title)).toEqual(["user_message", "reasoning"]);
    expect(chats.at(-1)?.message).toBe("Thinking");
  } finally {
    harness.restore();
  }
});

test("surfaces short server errors in detail rows", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=errors");
    harness.ready();
    harness.drain();
    harness.script.readError = true;
    harness.open("1");
    harness.drain();
    expect(harness.attempts.find((message) => message.action === "detail")?.message).toBe(
      "Connection failed: HTTP 500",
    );

    harness.script.readError = false;
    harness.script.sendError = true;
    harness.appmessage({ action: "send", thread: "1", message: "hello" });
    harness.drain();
    const details = harness.attempts.filter((message) => message.action === "detail");
    expect(details.at(-1)?.message).toBe("Could not send message: HTTP 500");
  } finally {
    harness.restore();
  }
});

test("clears the saved key and pairing from settings, keeping blank fields", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=settings");
    harness.ready();
    harness.drain();
    const saved = harness.attempts.length;
    harness.config({ url: "", key: "", access: "auto" });
    expect(harness.storage.data).toMatchObject({
      mcpUrl: "https://test",
      mcpToken: "watch-token",
      elevenKey: "eleven-key",
    });
    expect(harness.attempts).toHaveLength(saved);

    harness.config({ url: "", key: "", access: "auto", clearKey: true });
    expect(harness.storage.data.elevenKey).toBeUndefined();
    expect(harness.storage.data.mcpToken).toBe("watch-token");

    harness.config({ url: "", key: "new-key", access: "auto" });
    expect(harness.storage.data.elevenKey).toBe("new-key");

    harness.open("1");
    harness.drain();
    harness.script.holdThreads = true;
    harness.appmessage({ action: "list" });
    harness.config({ url: "", key: "", access: "auto", unpair: true });
    expect(harness.storage.data.mcpUrl).toBeUndefined();
    expect(harness.storage.data.mcpToken).toBeUndefined();
    expect(harness.poll).toThrow("no read poll scheduled");
    harness.releaseThreads();
    harness.drain();
    expect(
      harness.attempts.some(
        (message) => message.action === "thread" && message.title === "Pair in phone settings",
      ),
    ).toBe(true);
    expect(
      harness.attempts.some(
        (message) => message.action === "thread" && message.title.startsWith("Connection failed"),
      ),
    ).toBe(false);
  } finally {
    harness.restore();
  }
});

test("an empty thread clears the loading placeholder", async () => {
  const harness = await setup();
  try {
    await import("../src/pkjs/index.js?case=empty-thread");
    harness.ready();
    harness.drain();
    harness.script.items = [];
    harness.script.threadStatus = "idle";
    harness.open("thread-empty");
    harness.drain();

    expect(
      harness.attempts.some(
        (message) => message.action === "chat_clear" && message.thread === "thread-empty",
      ),
    ).toBe(true);
    expect(harness.attempts.at(-1)?.action).toBe("chat_show");
  } finally {
    harness.restore();
  }
});
